/** Numeric filament trajectories extracted from the user's visual reference
 * using a red-masked image-gradient structure tensor. These are actual 3D
 * geometry paths, not a raster texture. Z follows the modeled sheet relief.
 * 463 de-overlapped structural segments plus silhouette-bounded local fiber paths.
 */
const encoded='';
let decoded:Uint16Array|null=null;
export function referenceFilamentPaths(mobile:boolean):number[][][] {
  if(!decoded){const b=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));decoded=new Uint16Array(b.buffer)}
  const data=decoded,paths:number[][][]=[];let cursor=0,pathIndex=0;
  while(cursor<data.length){const count=data[cursor++],points:number[][]=[];const keep=!mobile||pathIndex<463||pathIndex%2===0;
    for(let i=0;i<count;i++){const x=data[cursor++]/4,y=data[cursor++]/4,z=data[cursor++]/16000-1,phase=data[cursor++];if(keep)points.push([(x-627)/250,(627-y)/250,z,(phase>>8)/255*Math.PI*2,(phase&255)/255,pathIndex])}
    if(keep)paths.push(points);pathIndex++;
  }
  return paths;
}
